-- Name: article_relationship_analytics; Type: MATERIALIZED VIEW; Schema: public; Owner: admin
--

CREATE MATERIALIZED VIEW public.article_relationship_analytics AS
 SELECT a1.author_name,
    a1.catagory,
    count(*) AS related_article_pairs
   FROM (public.articles a1
     JOIN public.articles a2 ON ((((a1.author_name)::text = (a2.author_name)::text) AND ((a1.catagory)::text = (a2.catagory)::text) AND (a1.id < a2.id) AND ((a2.published_date >= a1.published_date) AND (a2.published_date <= (a1.published_date + '24:00:00'::interval))))))
  GROUP BY a1.author_name, a1.catagory
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.article_relationship_analytics OWNER TO admin;

