--
-- Name: sales_summary_mv; Type: MATERIALIZED VIEW; Schema: public; Owner: admin
--

CREATE MATERIALIZED VIEW public.sales_summary_mv AS
 SELECT to_char((date(e.event_at))::timestamp with time zone, 'YYYY-MM-DD'::text) AS sale_date,
    pc.name AS plan,
    (e.metadata ->> 'target_type'::text) AS target_type,
    sum(e.amount) AS total_sales,
        CASE
            WHEN ((e.metadata ->> 'target_type'::text) = 'USER'::text) THEN count(DISTINCT p.user_id)
            WHEN ((e.metadata ->> 'target_type'::text) = 'ORG'::text) THEN count(DISTINCT p.organization_id)
            ELSE (0)::bigint
        END AS subscriber_count
   FROM (((public.pgledger_entries_view e
     JOIN public.pgledger_accounts_view a ON ((a.id = e.account_id)))
     LEFT JOIN public.payments p ON (((p.id)::text = (e.metadata ->> 'payment_id'::text))))
     LEFT JOIN public.plans_catalog pc ON (((pc.id)::text = (e.metadata ->> 'plan_id'::text))))
  WHERE ((a.name = 'sales_revenue'::text) AND (e.amount > (0)::numeric))
  GROUP BY (date(e.event_at)), pc.name, (e.metadata ->> 'target_type'::text)
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.sales_summary_mv OWNER TO admin;

